/* GuideJar embed wrapper */
.guidejarWrapper {
  position: relative;
  height: 0;
  width: 100%;
  overflow: hidden;
  z-index: var(--z-nav);
  border-radius: 10px;
  box-sizing: border-box;
  padding-bottom: calc(56.25% + 32px);
}

/* GuideJar iframe — fills the wrapper */
.guidejarIframe {
  position: absolute;
  inset: 0;
}

/* Typewriter span container */
.typewriterContainer {
  display: inline-block;
  min-width: 280px;
  min-height: 1.1em;
  text-align: left;
  vertical-align: baseline;
  /* Explicit fallback color so accessibility audits read correct contrast ratio.
     Visually the child .animate-span overrides this with #019ae6. */
  color: var(--color-brand-blue);
}

/* Typewriter animated word */
.typewriterWord {
  display: inline-block;
  /* Explicit fallback so motion.span inherits readable color in audit contexts. */
  color: var(--color-brand-blue);
}

/* CSS-driven phrase fade — replaces framer-motion AnimatePresence */
.typewriterFade {
  animation: typewriterFadeIn 0.28s ease-in-out;
}

@keyframes typewriterFadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .typewriterFade {
    animation: none;
  }
}

